import { TsSnippet } from "jsr:@skmtc/lang-typescript@0.10.4";
import type { GenerateContextType, GeneratorKey, Modifiers, OasDiscriminator, OasRef, OasSchema, RefName, TypeSystemValue } from 'jsr:@skmtc/core@0.16.1'
import { toZodValue } from "./Zod.ts";
import { applyModifiers } from "./applyModifiers.ts";

type ZodUnionArgs = {
  context: GenerateContextType;
  destinationPath: string;
  members: (OasSchema | OasRef<"schema">)[];
  /** The originating union schema node — for fine-grained attribution. */
  schema?: OasSchema | OasRef<"schema">;
  discriminator?: OasDiscriminator;
  modifiers: Modifiers;
  generatorKey: GeneratorKey;
  rootRef?: RefName;
};

export class ZodUnion extends TsSnippet {
  type = "union" as const;
  members: TypeSystemValue[];
  discriminator: string | undefined;
  modifiers: Modifiers;

  constructor({
    context,
    generatorKey,
    destinationPath,
    members,
    discriminator,
    modifiers,
    rootRef,
    schema,
  }: ZodUnionArgs) {
    super({ context, generatorKey, stackTrail: schema?.stackTrail.clone() });

    this.members = members.map((member) => {
      return toZodValue({
        destinationPath,
        schema: member,
        required: true,
        context,
        rootRef,
      });
    });

    this.discriminator = discriminator?.propertyName;
    this.modifiers = modifiers;

    this.register({ imports: { zod: ["z"] }, destinationPath });
  }

  override toString(): string {
    const members = this.members.map((member) => `${member}`).join(", ");

    const content = this.discriminator
      ? `z.discriminatedUnion("${this.discriminator}", [${members}])`
      : `z.union([${members}])`;

    return applyModifiers(content, this.modifiers);
  }
}

