import { IdentifierBase } from 'jsr:@skmtc/core@0.28.3'
import type { IdentifierBaseArgs, IdentifierType } from 'jsr:@skmtc/core@0.28.3'
import { toTsKeyword, type TsEntityType } from './createIdentifier.ts'

/**
 * The non-`name` parts of a TypeScript identifier — core's neutral
 * {@link IdentifierType} with its `type` narrowed to TypeScript's fixed
 * {@link TsEntityType} vocabulary. This is the named form generators annotate
 * `toIdentifierType` with; a projection-base veneer threads it as the config's
 * `IdType` so the return tightens with no recast. The engine spreads it into
 * `lang.toIdentifier({ name, ...identifierType })`.
 */
export type TsIdentifierType = IdentifierType & { type: TsEntityType }

/**
 * Constructor arguments for {@link TsIdentifier} — the neutral
 * {@link IdentifierBaseArgs} plus this language's typed `type`.
 */
export type TsIdentifierArgs = IdentifierBaseArgs & {
  type: TsEntityType
}

/**
 * TypeScript's concrete {@link IdentifierBase}: adds the typed `type`
 * ({@link TsEntityType}) the renderer reads to pick its declaration keyword
 * (`const` / `type`) and its import form (plain / type-only).
 */
export class TsIdentifier extends IdentifierBase {
  /** Per-language declaration type — `const` / `type` and import form. */
  type: TsEntityType

  constructor({ name, typeName, exported, type }: TsIdentifierArgs) {
    super({ name, typeName, exported })
    this.type = type
  }

  /**
   * TypeScript's declaration slot is the declaration header `<keyword> <name>`
   * (`const thing`, `class Thing`, `declare namespace Thing`) — exactly how
   * the declaration opens. A `class Foo` and a `declare namespace Foo` are
   * separate declarations the compiler merges, so the differing keyword keeps
   * their keys distinct while exact repeats still collapse.
   */
  override declarationKey(): string {
    return `${toTsKeyword(this.type)} ${this.name}`
  }
}

import type { OasRef } from '../oas/ref/Ref.ts'
import type { OasSchema } from '../oas/schema/Schema.ts'
import type { Modifiers } from './Modifiers.ts'
import type { Stringable } from '../dsl/Stringable.ts'
import type { GenerateContextType } from '../context/generateTypes.ts'
import type { CustomValue } from '../dsl/CustomValue.ts'
import type { OasVoid } from '../oas/void/Void.ts'
import type { GeneratorKey } from '../dsl/GeneratorKeys.ts'
import type { RefName } from './RefName.ts'

/**
 * Union type representing all possible type system values in the SKMTC code generation system.
 *
 * The `TypeSystemValue` represents the normalized intermediate representation used by SKMTC
 * to convert OpenAPI schemas into target language types. This type system abstracts away
 * OpenAPI-specific details and provides a consistent interface for generating code in
 * different target languages and frameworks.
 *
 * ## Type Categories
 *
 * - **Primitive Types**: `string`, `number`, `integer`, `boolean`, `null`
 * - **Complex Types**: `array`, `object`, `union`
 * - **Special Types**: `void`, `never`, `unknown`, `custom`
 * - **Reference Types**: `ref` for schema references
 *
 * @example Discriminated union usage
 * ```typescript
 * import { TypeSystemValue } from '@skmtc/core';
 *
 * function processType(type: TypeSystemValue): string {
 *   switch (type.type) {
 *     case 'string':
 *       return `string${type.modifiers.optional ? '?' : ''}`;
 *     case 'array':
 *       return `${processType(type.items)}[]`;
 *     case 'object':
 *       return 'object';
 *     case 'ref':
 *       return type.name;
 *     default:
 *       return type.type;
 *   }
 * }
 * ```
 *
 * @example In generator contexts
 * ```typescript
 * class TypeScriptGenerator {
 *   generateType(typeValue: TypeSystemValue): string {
 *     if (typeValue.type === 'union') {
 *       return typeValue.members
 *         .map(member => this.generateType(member))
 *         .join(' | ');
 *     }
 *
 *     if (typeValue.type === 'array') {
 *       return `${this.generateType(typeValue.items)}[]`;
 *     }
 *
 *     // Handle other types...
 *     return typeValue.type;
 *   }
 * }
 * ```
 */
export type TypeSystemValue =
  | TypeSystemArray
  | TypeSystemObject
  | TypeSystemUnion
  | TypeSystemString
  | TypeSystemNumber
  | TypeSystemInteger
  | TypeSystemBoolean
  | TypeSystemUnknown
  | TypeSystemVoid
  | TypeSystemNever
  | TypeSystemRef
  | TypeSystemNull
  | TypeSystemCustom

/**
 * Type system representation of a reference to another schema.
 *
 * `TypeSystemRef` represents references to other schemas, typically used for
 * complex types that are defined elsewhere in the schema and referenced
 * through `$ref` in OpenAPI specifications.
 *
 * @example
 * ```typescript
 * const userRef: TypeSystemRef = {
 *   type: 'ref',
 *   name: 'User',
 *   modifiers: { optional: false, nullable: false },
 *   generatorKey: 'model|User'
 * };
 * ```
 */
export type TypeSystemRef = {
  /** Discriminator for the reference type */
  type: 'ref'
  /** The name of the referenced schema */
  name: string
  /** Type modifiers (optional, nullable, etc.) */
  modifiers: Modifiers
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation for custom, generator-specific types.
 *
 * `TypeSystemCustom` allows generators to inject custom type representations
 * that don't fit into standard OpenAPI types. The value is a `Stringable`
 * that will be rendered directly in the generated code.
 *
 * @example
 * ```typescript
 * const customType: TypeSystemCustom = {
 *   type: 'custom',
 *   value: 'React.ReactNode',
 *   generatorKey: 'react-component|Button'
 * };
 * ```
 */
export type TypeSystemCustom = {
  /** Discriminator for the custom type */
  type: 'custom'
  /** The custom type value to be rendered */
  value: Stringable
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation of array types.
 *
 * @example
 * ```typescript
 * const stringArray: TypeSystemArray = {
 *   type: 'array',
 *   items: { type: 'string', modifiers: { optional: false, nullable: false } },
 *   modifiers: { optional: false, nullable: false }
 * };
 * ```
 */
export type TypeSystemArray = {
  /** Discriminator for the array type */
  type: 'array'
  /** The type of items in the array */
  items: TypeSystemValue
  /** Type modifiers (optional, nullable, etc.) */
  modifiers: Modifiers
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation of floating-point number types.
 *
 * @example
 * ```typescript
 * const priceType: TypeSystemNumber = {
 *   type: 'number',
 *   modifiers: { optional: false, nullable: false }
 * };
 * ```
 */
export type TypeSystemNumber = {
  /** Discriminator for the number type */
  type: 'number'
  /** Type modifiers (optional, nullable, etc.) */
  modifiers: Modifiers
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation of void types (no value).
 *
 * @example
 * ```typescript
 * const voidType: TypeSystemVoid = {
 *   type: 'void'
 * };
 * ```
 */
export type TypeSystemVoid = {
  /** Discriminator for the void type */
  type: 'void'
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation of never types (impossible values).
 *
 * @example
 * ```typescript
 * const neverType: TypeSystemNever = {
 *   type: 'never'
 * };
 * ```
 */
export type TypeSystemNever = {
  /** Discriminator for the never type */
  type: 'never'
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation of integer number types.
 *
 * @example
 * ```typescript
 * const countType: TypeSystemInteger = {
 *   type: 'integer',
 *   modifiers: { optional: false, nullable: false }
 * };
 * ```
 */
export type TypeSystemInteger = {
  /** Discriminator for the integer type */
  type: 'integer'
  /** Type modifiers (optional, nullable, etc.) */
  modifiers: Modifiers
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation of boolean types.
 *
 * @example
 * ```typescript
 * const flagType: TypeSystemBoolean = {
 *   type: 'boolean',
 *   modifiers: { optional: false, nullable: false }
 * };
 * ```
 */
export type TypeSystemBoolean = {
  /** Discriminator for the boolean type */
  type: 'boolean'
  /** Type modifiers (optional, nullable, etc.) */
  modifiers: Modifiers
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation of unknown types.
 *
 * @example
 * ```typescript
 * const unknownType: TypeSystemUnknown = {
 *   type: 'unknown'
 * };
 * ```
 */
export type TypeSystemUnknown = {
  /** Discriminator for the unknown type */
  type: 'unknown'
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation of null types.
 *
 * @example
 * ```typescript
 * const nullType: TypeSystemNull = {
 *   type: 'null'
 * };
 * ```
 */
export type TypeSystemNull = {
  /** Discriminator for the null type */
  type: 'null'
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation of record types (key-value mappings).
 *
 * @example
 * ```typescript
 * const recordType: TypeSystemRecord = {
 *   value: { type: 'string', modifiers: { optional: false, nullable: false } }
 * };
 * ```
 */
export type TypeSystemRecord = {
  /** The type of values in the record, or 'true' for any value */
  value: TypeSystemValue | 'true'
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation of object properties.
 *
 * @example
 * ```typescript
 * const objectProps: TypeSystemObjectProperties = {
 *   properties: {
 *     name: { type: 'string', modifiers: { optional: false, nullable: false } },
 *     age: { type: 'integer', modifiers: { optional: true, nullable: false } }
 *   }
 * };
 * ```
 */
export type TypeSystemObjectProperties = {
  /** Map of property names to their types */
  properties: Record<string, TypeSystemValue>
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation of string types.
 *
 * @example
 * ```typescript
 * const emailString: TypeSystemString = {
 *   type: 'string',
 *   format: 'email',
 *   enums: undefined,
 *   modifiers: { optional: false, nullable: false }
 * };
 *
 * const statusEnum: TypeSystemString = {
 *   type: 'string',
 *   format: undefined,
 *   enums: ['active', 'inactive', 'pending'],
 *   modifiers: { optional: false, nullable: false }
 * };
 * ```
 */
export type TypeSystemString = {
  /** Discriminator for the string type */
  type: 'string'
  /** String format specification (email, uuid, date-time, etc.) */
  format: string | undefined
  /** Array of allowed enum values */
  enums: string[] | (string | null)[] | undefined
  /** Type modifiers (optional, nullable, etc.) */
  modifiers: Modifiers
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation of union types.
 *
 * @example
 * ```typescript
 * const stringOrNumber: TypeSystemUnion = {
 *   type: 'union',
 *   members: [
 *     { type: 'string', modifiers: { optional: false, nullable: false } },
 *     { type: 'number', modifiers: { optional: false, nullable: false } }
 *   ],
 *   discriminator: undefined,
 *   modifiers: { optional: false, nullable: false }
 * };
 *
 * const discriminatedUnion: TypeSystemUnion = {
 *   type: 'union',
 *   members: [userType, adminType, guestType],
 *   discriminator: 'type',
 *   modifiers: { optional: false, nullable: false }
 * };
 * ```
 */
export type TypeSystemUnion = {
  /** Discriminator for the union type */
  type: 'union'
  /** Array of types that are part of the union */
  members: TypeSystemValue[]
  /** Optional discriminator property name for tagged unions */
  discriminator: string | undefined
  /** Type modifiers (optional, nullable, etc.) */
  modifiers: Modifiers
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Type system representation of object types.
 *
 * Objects can have either fixed properties (objectProperties) or
 * dynamic key-value pairs (recordProperties), or both.
 *
 * @example Fixed properties object
 * ```typescript
 * const userObject: TypeSystemObject = {
 *   type: 'object',
 *   recordProperties: null,
 *   objectProperties: {
 *     properties: {
 *       id: { type: 'string', modifiers: { optional: false, nullable: false } },
 *       name: { type: 'string', modifiers: { optional: false, nullable: false } },
 *       email: { type: 'string', modifiers: { optional: true, nullable: false } }
 *     }
 *   },
 *   modifiers: { optional: false, nullable: false }
 * };
 * ```
 *
 * @example Record-like object
 * ```typescript
 * const configObject: TypeSystemObject = {
 *   type: 'object',
 *   recordProperties: {
 *     value: { type: 'string', modifiers: { optional: false, nullable: false } }
 *   },
 *   objectProperties: null,
 *   modifiers: { optional: false, nullable: false }
 * };
 * ```
 */
export type TypeSystemObject = {
  /** Discriminator for the object type */
  type: 'object'
  /** Dynamic key-value properties (Record<string, T>) */
  recordProperties: TypeSystemRecord | null
  /** Fixed object properties with known keys */
  objectProperties: TypeSystemObjectProperties | null
  /** Type modifiers (optional, nullable, etc.) */
  modifiers: Modifiers
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

/**
 * Mapping of schema types to their type system representations.
 *
 * This type maps OpenAPI schema types to their corresponding type system
 * value types, enabling type-safe transformations during code generation.
 *
 * @example
 * ```typescript
 * // Used internally by the type system transformation process
 * type StringOutput = SchemaToTypeSystemMap['string']['output']; // TypeSystemString
 * type RefSource = SchemaToTypeSystemMap['ref']['source']; // OasRef<'schema'>
 * ```
 */
export type SchemaToTypeSystemMap = {
  ref: {
    source: OasRef<'schema'>
    output: TypeSystemRef
  }
  array: {
    source: OasSchema
    output: TypeSystemArray
  }
  number: {
    source: OasSchema
    output: TypeSystemNumber
  }
  void: {
    source: OasVoid
    output: TypeSystemVoid
  }
  integer: {
    source: OasSchema
    output: TypeSystemInteger
  }
  boolean: {
    source: OasSchema
    output: TypeSystemBoolean
  }
  unknown: {
    source: OasSchema
    output: TypeSystemUnknown
  }
  null: {
    source: OasSchema
    output: TypeSystemNull
  }
  object: {
    source: OasSchema
    output: TypeSystemObject
  }
  string: {
    source: OasSchema
    output: TypeSystemString
  }
  union: {
    source: OasSchema
    output: TypeSystemUnion
  }
  custom: {
    source: CustomValue
    output: TypeSystemCustom
  }
}

/**
 * Union of all possible schema types that can be transformed.
 *
 * @example
 * ```typescript
 * function transformSchema(schema: SchemaType): TypeSystemValue {
 *   // Transform any schema type to its type system representation
 *   return toTypeSystemValue(schema);
 * }
 * ```
 */
export type SchemaType = OasSchema | OasRef<'schema'> | OasVoid | CustomValue

/**
 * Extracts only reference types from a schema type.
 *
 * @template Schema - The schema type to filter
 * @example
 * ```typescript
 * type RefOnly = SchemaToRef<OasRef<'schema'>>; // OasRef<'schema'>
 * type NeverForSchema = SchemaToRef<OasSchema>; // never
 * ```
 */
export type SchemaToRef<Schema extends SchemaType> =
  Schema extends OasRef<'schema'> ? Schema : never

/**
 * Extracts only non-reference types from a schema type.
 *
 * @template Schema - The schema type to filter
 * @example
 * ```typescript
 * type SchemaOnly = SchemaToNonRef<OasSchema>; // OasSchema
 * type NeverForRef = SchemaToNonRef<OasRef<'schema'>>; // never
 * ```
 */
export type SchemaToNonRef<Schema extends SchemaType> =
  Schema extends OasRef<'schema'> ? never : Schema

/**
 * Gets the output type for a given schema type key.
 *
 * @template T - The schema type key
 * @example
 * ```typescript
 * type StringOutput = TypeSystemOutput<'string'>; // TypeSystemString
 * type ArrayOutput = TypeSystemOutput<'array'>; // TypeSystemArray
 * ```
 */
export type TypeSystemOutput<T extends keyof SchemaToTypeSystemMap> =
  SchemaToTypeSystemMap[T]['output']

/**
 * Arguments for type system transformation functions.
 *
 * @template Schema - The specific schema type being transformed
 * @example
 * ```typescript
 * function transformStringSchema(args: TypeSystemArgs<OasSchema>): TypeSystemString {
 *   const { context, schema, required } = args;
 *   // Transform string schema to type system representation
 *   return {
 *     type: 'string',
 *     format: schema.format,
 *     enums: schema.enums,
 *     modifiers: { optional: !required, nullable: schema.nullable }
 *   };
 * }
 * ```
 */
export type TypeSystemArgs<Schema extends SchemaType> = {
  /** The generation context containing utilities and state */
  context: GenerateContextType
  /** The destination path for the generated artifact */
  destinationPath: string
  /** The schema to transform */
  schema: Schema
  /** Optional root reference name for schema references */
  rootRef?: RefName
  /** Whether the schema field is required */
  required: boolean | undefined
}

/**
 * Function type for transforming schemas to type system values.
 *
 * @template Schema - The schema type being transformed
 * @param args - Transformation arguments
 * @returns The corresponding type system value
 *
 * @example
 * ```typescript
 * const transformSchema: SchemaToValueFn = (args) => {
 *   switch (args.schema.type) {
 *     case 'string':
 *       return transformStringSchema(args);
 *     case 'object':
 *       return transformObjectSchema(args);
 *     // ... other cases
 *     default:
 *       throw new Error(`Unknown schema type: ${args.schema.type}`);
 *   }
 * };
 * ```
 */
export type SchemaToValueFn = <Schema extends SchemaType>(
  args: TypeSystemArgs<Schema>
) => TypeSystemOutput<Schema['type']>

/**
 * @fileoverview Generator Key System for SKMTC Core
 *
 * This module provides a comprehensive type-safe key system for identifying and
 * organizing generated content within the SKMTC pipeline. Generator keys provide
 * unique identification for operations, models, and other generated artifacts,
 * ensuring proper organization and preventing collisions.
 *
 * The key system uses branded types to ensure type safety and provides utilities
 * for creating, parsing, and manipulating keys throughout the generation process.
 *
 * ## Key Features
 *
 * - **Type Safety**: Branded types prevent mixing different kinds of keys
 * - **Unique Identification**: Composite keys ensure global uniqueness
 * - **Parsing Utilities**: Safe extraction of components from composite keys
 * - **Generator Organization**: Clear mapping between generators and their artifacts
 * - **Reference Integration**: Seamless integration with OpenAPI reference system
 *
 * @example Creating an OAS operation generator key
 * ```typescript
 * import { toOasOperationGeneratorKey, fromGeneratorKey } from '@skmtc/core/GeneratorKeys';
 *
 * const key = toOasOperationGeneratorKey({
 *   generatorId: 'api-client',
 *   path: '/users',
 *   method: 'get'
 * });
 *
 * const parsed = fromGeneratorKey(key);
 * if (parsed.type === 'oasOperation') {
 *   console.log(parsed); // { type: 'oasOperation', generatorId: 'api-client', path: '/users', method: 'get' }
 * }
 * ```
 *
 * @example Creating a GraphQL operation generator key
 * ```typescript
 * import { toGqlOperationGeneratorKey, fromGeneratorKey } from '@skmtc/core/GeneratorKeys';
 *
 * const key = toGqlOperationGeneratorKey({
 *   generatorId: 'graphql-client',
 *   rootKind: 'query',
 *   fieldName: 'getUser'
 * });
 *
 * const parsed = fromGeneratorKey(key);
 * if (parsed.type === 'gqlOperation') {
 *   console.log(parsed); // { type: 'gqlOperation', generatorId: 'graphql-client', rootKind: 'query', fieldName: 'getUser' }
 * }
 * ```
 *
 * @example Working with model keys
 * ```typescript
 * import { toModelGeneratorKey } from '@skmtc/core/GeneratorKeys';
 * import type { RefName } from '@skmtc/core/RefName';
 *
 * const modelKey = toModelGeneratorKey({
 *   generatorId: 'typescript-models',
 *   refName: 'User' as RefName,
 *   variant: 'main'
 * });
 * ```
 *
 * @module GeneratorKeys
 */

import type { OasOperation } from '../oas/operation/Operation.ts'
import type { OasWebhook } from '../oas/webhook/Webhook.ts'
import type { GqlOperation, GqlRootKind } from '../gql/operation/GqlOperation.ts'
import type { Brand } from '../types/Brand.ts'
import type { RefName } from '../types/RefName.ts'
import { type Method, isMethod } from '../types/Method.ts'
import { DEFAULT_VARIANT } from '../types/Variant.ts'

const GQL_ROOT_KINDS: readonly GqlRootKind[] = ['query', 'mutation', 'subscription']

const isGqlRootKind = (value: string): value is GqlRootKind =>
  (GQL_ROOT_KINDS as readonly string[]).includes(value)

/**
 * Template literal type for OAS operation generator keys before branding.
 * Format: `generatorId|path|method|variant`
 * (e.g., 'api-client|/users|get|main', 'forms|/quotes|patch|customer').
 *
 * The trailing `variant` segment carries the operation-variant axis
 * (see {@link Variant}). For variants-unaware generators it is always
 * `'main'`; for variants-aware generators it carries the per-call
 * variant name.
 */
export type NakedOasOperationGeneratorKey = `${string}|${string}|${Method}|${string}`

/**
 * Template literal type for GraphQL operation generator keys before branding.
 * Format: `generatorId|rootKind|fieldName|variant`
 * (e.g., 'graphql-client|query|getUser|main',
 * 'graphql-client|mutation|createPost|customer').
 *
 * The trailing `variant` segment carries the operation-variant axis
 * (see {@link Variant}).
 */
export type NakedGqlOperationGeneratorKey = `${string}|${GqlRootKind}|${string}|${string}`

/**
 * Template literal type for model generator keys before branding.
 * Format: `generatorId|refName|variant`
 * (e.g., 'typescript-models|User|main',
 * 'zod-schemas|Customer|coercive').
 *
 * The trailing `variant` segment carries the model-variant axis
 * (see {@link Variant}). For variants-unaware generators it is always
 * `'main'`; for variants-aware generators it carries the per-call
 * variant name. The shape mirrors the operation key so the integrity
 * check in `ModelDriver.affirmDefinition` catches a variants-aware
 * generator that forgot to fold `variant` into its `toIdentifier`.
 */
export type NakedModelGeneratorKey = `${string}|${string}|${string}`

/**
 * Template literal type for webhook generator keys before branding.
 * Format: `generatorId|webhook|name|method|variant`
 * (e.g., 'webhook-handlers|webhook|newPet|post|main').
 *
 * The literal `webhook` segment in position 2 distinguishes webhook keys
 * (5 segments) from operation keys (`generatorId|path|method|variant`, 4
 * segments), so a webhook named `users` never collides with a path
 * `/users` in the key space or the `(name, exportPath)` cache. The
 * trailing `variant` segment carries the variant axis (see {@link Variant}).
 */
export type NakedWebhookGeneratorKey = `${string}|webhook|${string}|${Method}|${string}`

/**
 * Branded type for OAS operation generator keys.
 *
 * Uniquely identifies a generator processing a specific OpenAPI operation —
 * encodes generator ID, API path, and HTTP method. See
 * {@link GqlOperationGeneratorKey} for the GraphQL counterpart.
 */
export type OasOperationGeneratorKey = Brand<
  NakedOasOperationGeneratorKey,
  'OasOperationGeneratorKey'
>

/**
 * Branded type for GraphQL operation generator keys.
 *
 * Sibling to {@link OasOperationGeneratorKey} for the GraphQL protocol. The key
 * encodes the generator ID, the root type (`query` / `mutation` /
 * `subscription`), and the root field name.
 */
export type GqlOperationGeneratorKey = Brand<
  NakedGqlOperationGeneratorKey,
  'GqlOperationGeneratorKey'
>

/**
 * Branded type for model generator keys.
 *
 * Model generator keys uniquely identify generators that process
 * OpenAPI schema models. The key encodes the generator ID and
 * the schema reference name.
 */
export type ModelGeneratorKey = Brand<NakedModelGeneratorKey, 'ModelGeneratorKey'>

/**
 * Branded type for webhook generator keys.
 *
 * Sibling to {@link OasOperationGeneratorKey} for the OpenAPI 3.1 webhook
 * subject. The literal `webhook` discriminator segment keeps it from
 * colliding with operation keys in the `(name, exportPath)` cache and the
 * key space.
 */
export type WebhookGeneratorKey = Brand<NakedWebhookGeneratorKey, 'WebhookGeneratorKey'>

/**
 * Branded type for generator-only keys.
 *
 * Generator-only keys identify generators that don't process specific
 * operations or models, but generate global artifacts like configuration
 * files, base classes, or utility modules.
 */
export type GeneratorOnlyKey = Brand<string, 'GeneratorOnlyKey'>

/**
 * Union type of all possible generator key types.
 *
 * Generator keys serve as unique identifiers for different types of
 * code generators in the SKMTC system. They enable tracking, caching,
 * and dependency management between generated artifacts.
 *
 * @example
 * ```typescript
 * // OAS operation generator key
 * const opKey: GeneratorKey = toOasOperationGeneratorKey({
 *   generatorId: 'api-client',
 *   path: '/users/{id}',
 *   method: 'get'
 * });
 *
 * // GraphQL operation generator key
 * const gqlKey: GeneratorKey = toGqlOperationGeneratorKey({
 *   generatorId: 'graphql-client',
 *   rootKind: 'query',
 *   fieldName: 'getUser'
 * });
 *
 * // Model generator key
 * const modelKey: GeneratorKey = toModelGeneratorKey({
 *   generatorId: 'typescript-types',
 *   refName: 'User',
 *   variant: 'main'
 * });
 *
 * // Generator-only key
 * const globalKey: GeneratorKey = toGeneratorOnlyKey({
 *   generatorId: 'api-config'
 * });
 * ```
 */
export type GeneratorKey =
  | OasOperationGeneratorKey
  | WebhookGeneratorKey
  | GqlOperationGeneratorKey
  | ModelGeneratorKey
  | GeneratorOnlyKey

/**
 * Arguments for {@link toOasOperationGeneratorKey}.
 *
 * Can specify operation details directly or provide an OasOperation
 * object from which the path and method will be extracted. The
 * `variant` segment is always required so the resulting key
 * disambiguates per-variant Definitions (see {@link Variant}).
 */
type ToOasOperationGeneratorKeyArgs =
  | {
      /** Unique identifier for the generator */
      generatorId: string
      /** API path (e.g., '/users/{id}') */
      path: string
      /** HTTP method */
      method: Method
      /** Operation variant name — omitted means `'main'` */
      variant?: string
    }
  | {
      /** Unique identifier for the generator */
      generatorId: string
      /** OpenAPI operation object containing path and method */
      operation: OasOperation
      /** Operation variant name — omitted means `'main'` */
      variant?: string
    }

/**
 * Creates an OAS operation generator key from generator ID and operation details.
 *
 * Uniquely identifies a generator processing a specific API operation. The
 * key format is: `generatorId|path|method`. See
 * {@link toGqlOperationGeneratorKey} for the GraphQL counterpart.
 *
 * @param args - Key construction arguments
 * @returns A branded OasOperationGeneratorKey
 *
 * @example With explicit path and method
 * ```typescript
 * const key = toOasOperationGeneratorKey({
 *   generatorId: 'api-client',
 *   path: '/users/{id}',
 *   method: 'get'
 * });
 * // Result: 'api-client|/users/{id}|get' (branded)
 * ```
 *
 * @example With OasOperation object
 * ```typescript
 * const operation = new OasOperation({
 *   path: '/posts',
 *   method: 'post',
 *   // ... other operation details
 * });
 *
 * const key = toOasOperationGeneratorKey({
 *   generatorId: 'rest-client',
 *   operation
 * });
 * // Result: 'rest-client|/posts|post' (branded)
 * ```
 */
export const toOasOperationGeneratorKey = ({
  generatorId,
  variant = DEFAULT_VARIANT,
  ...rest
}: ToOasOperationGeneratorKeyArgs): OasOperationGeneratorKey => {
  const { path, method } = 'operation' in rest ? rest.operation : rest

  const nakedKey: NakedOasOperationGeneratorKey = `${generatorId}|${path}|${method}|${variant}`

  return nakedKey as OasOperationGeneratorKey
}

/**
 * Arguments for {@link toWebhookGeneratorKey}.
 *
 * Can specify webhook details directly or provide an {@link OasWebhook}
 * object from which the name and method will be extracted. The `variant`
 * segment is always required so the resulting key disambiguates
 * per-variant Definitions (see {@link Variant}).
 */
type ToWebhookGeneratorKeyArgs =
  | {
      /** Unique identifier for the generator */
      generatorId: string
      /** Webhook name (the `webhooks` map key — NOT a URL path) */
      name: string
      /** HTTP method */
      method: Method
      /** Webhook variant name — omitted means `'main'` */
      variant?: string
    }
  | {
      /** Unique identifier for the generator */
      generatorId: string
      /** OpenAPI webhook object containing name and method */
      webhook: OasWebhook
      /** Webhook variant name — omitted means `'main'` */
      variant?: string
    }

/**
 * Creates a webhook generator key from generator ID and webhook details.
 *
 * Sibling to {@link toOasOperationGeneratorKey} for the 3.1 webhook subject.
 * Format: `generatorId|webhook|name|method|variant`. The literal `webhook`
 * segment keeps webhook keys from colliding with operation keys.
 */
export const toWebhookGeneratorKey = ({
  generatorId,
  variant = DEFAULT_VARIANT,
  ...rest
}: ToWebhookGeneratorKeyArgs): WebhookGeneratorKey => {
  const { name, method } = 'webhook' in rest ? rest.webhook : rest

  const nakedKey: NakedWebhookGeneratorKey = `${generatorId}|webhook|${name}|${method}|${variant}`

  return nakedKey as WebhookGeneratorKey
}

/**
 * Arguments for {@link toGqlOperationGeneratorKey}.
 *
 * Can specify operation details directly or provide a {@link GqlOperation}
 * object from which the root type and field name will be extracted. The
 * `variant` segment is always required (see {@link Variant}).
 */
type ToGqlOperationGeneratorKeyArgs =
  | {
      /** Unique identifier for the generator */
      generatorId: string
      /** GraphQL root type */
      rootKind: GqlRootKind
      /** Root field name */
      fieldName: string
      /** Operation variant name — omitted means `'main'` */
      variant?: string
    }
  | {
      /** Unique identifier for the generator */
      generatorId: string
      /** GraphQL operation object */
      operation: GqlOperation
      /** Operation variant name — omitted means `'main'` */
      variant?: string
    }

/**
 * Creates a GraphQL operation generator key.
 *
 * Sibling to {@link toOasOperationGeneratorKey} for the GraphQL protocol. Format:
 * `generatorId|rootKind|fieldName|variant`.
