    'operation' in rest
      ? { rootKind: rest.operation.rootKind, fieldName: rest.operation.fieldName }
      : rest

  const nakedKey: NakedGqlOperationGeneratorKey = `${generatorId}|${rootKind}|${fieldName}|${variant}`

