  if (isOasOperationGeneratorKey(generatorKey)) {
    return generatorKey.split('|')[0]
  }

  if (isWebhookGeneratorKey(generatorKey)) {
    return generatorKey.split('|')[0]
  }

  if (isGqlOperationGeneratorKey(generatorKey)) {
    return generatorKey.split('|')[0]
  }

  if (isModelGeneratorKey(generatorKey)) {
    return generatorKey.split('|')[0]
  }

  return generatorKey
