import { TsSnippet } from '@skmtc/lang-typescript'
import type {
  GenerateContextType,
  GeneratorKey,
  Modifiers,
  OasBoolean,
  OasInteger,
  OasNumber,
  OasSchema,
  OasString,
  OasUnknown
} from '@skmtc/core'
import { applyModifiers } from './applyModifiers.ts'
import { EFFECT_MODULE, SCHEMA } from './constants.ts'

type ScalarArgs<Schema> = {
  context: GenerateContextType
  destinationPath: string
  schema: Schema
  modifiers: Modifiers
  generatorKey: GeneratorKey
}

/**
 * Shared base for the leaf snippets: every one of them registers the
 * `import { Schema } from 'effect'` its rendering depends on, and every one
 * of them renders a single expression wrapped in its modifiers. Subclasses
 * supply only that expression.
 */
abstract class EffectScalar<Schema> extends TsSnippet {
  modifiers: Modifiers
  schema: Schema

  constructor({ context, destinationPath, schema, modifiers, generatorKey }: ScalarArgs<Schema>) {
    super({
      context,
      generatorKey,
      stackTrail:
        schema && typeof schema === 'object' && 'stackTrail' in schema
          ? (schema as { stackTrail: { clone: () => never } }).stackTrail.clone()
          : undefined
    })

    this.schema = schema
    this.modifiers = modifiers

    this.register({ imports: { [EFFECT_MODULE]: [SCHEMA] }, destinationPath })
  }

  /** The bare effect Schema expression, before modifiers are applied. */
  protected abstract toExpression(): string

  override toString(): string {
    return applyModifiers(this.toExpression(), this.modifiers)
  }
}

/**
 * A string, or — when the schema carries an `enum` — the literal union of
 * its values: `Schema.Literal('pending', 'paid', …)`. A single-value enum
 * still renders `Schema.Literal(…)`, which is effect's exact-value schema.
 */
export class EffectString extends EffectScalar<OasString> {
  type = 'string' as const

  protected override toExpression(): string {
    const { enums } = this.schema

    if (!Array.isArray(enums) || enums.length === 0) {
      return `${SCHEMA}.String`
    }

    const literals = enums
      .map(value => (value === null ? 'null' : `'${value.replaceAll("'", "\\'")}'`))
      .join(', ')

    return `${SCHEMA}.Literal(${literals})`
  }
}

export class EffectNumber extends EffectScalar<OasNumber> {
  type = 'number' as const

  protected override toExpression(): string {
    return `${SCHEMA}.Number`
  }
}

/** `Schema.Int` is effect's `Number` narrowed by the `int` refinement. */
export class EffectInteger extends EffectScalar<OasInteger> {
  type = 'integer' as const

  protected override toExpression(): string {
    return `${SCHEMA}.Int`
  }
}

export class EffectBoolean extends EffectScalar<OasBoolean> {
  type = 'boolean' as const

  protected override toExpression(): string {
    return `${SCHEMA}.Boolean`
  }
}

export class EffectUnknown extends EffectScalar<OasUnknown | OasSchema | undefined> {
  type = 'unknown' as const

  protected override toExpression(): string {
    return `${SCHEMA}.Unknown`
  }
}

export class EffectVoid extends EffectScalar<undefined> {
  type = 'void' as const

  protected override toExpression(): string {
    return `${SCHEMA}.Void`
  }
}

