 * expression wrapped in its modifiers. Subclasses supply only that
 * expression.
 */
abstract class EffectScalar extends TsSnippet {
  modifiers: Modifiers

  constructor({ context, destinationPath, modifiers, generatorKey, stackTrail }: ScalarArgs) {
    super({ context, generatorKey, stackTrail })

    this.modifiers = modifiers

    this.register({ imports: { [EFFECT_MODULE]: [SCHEMA] }, destinationPath })
  }

  /** The bare effect Schema expression, before modifiers are applied. */
  protected abstract toExpression(): string

  override toString(): string {
    return applyModifiers(this.toExpression(), this.modifiers)
  }
}

type EffectStringArgs = ScalarArgs & { stringSchema: OasString }

/**
 * A string, or — when the schema carries an `enum` — the literal union of
 * its values: `Schema.Literal('pending', 'paid', …)`. A single-value enum
 * still renders `Schema.Literal(…)`, which is effect's exact-value schema.
 */
export class EffectString extends EffectScalar {
  type = 'string' as const
  enums: string[] | (string | null)[] | undefined
  format: string | undefined

  constructor({ stringSchema, ...rest }: EffectStringArgs) {
    super(rest)

    this.enums = stringSchema.enums
    this.format = stringSchema.format
  }

  protected override toExpression(): string {
    const { enums } = this

    if (!Array.isArray(enums) || enums.length === 0) {
      return `${SCHEMA}.String`
    }

    const literals = enums
      .map(value => (value === null ? 'null' : `'${value.replaceAll("'", "\\'")}'`))
      .join(', ')

    return `${SCHEMA}.Literal(${literals})`
  }
}

export class EffectNumber extends EffectScalar {
  type = 'number' as const

  protected override toExpression(): string {
    return `${SCHEMA}.Number`
  }
}

/** `Schema.Int` is effect's `Number` narrowed by the `int` refinement. */
export class EffectInteger extends EffectScalar {
  type = 'integer' as const

  protected override toExpression(): string {
    return `${SCHEMA}.Int`
  }
}

export class EffectBoolean extends EffectScalar {
  type = 'boolean' as const

  protected override toExpression(): string {
    return `${SCHEMA}.Boolean`
  }
}

export class EffectUnknown extends EffectScalar {
  type = 'unknown' as const

  protected override toExpression(): string {
    return `${SCHEMA}.Unknown`
  }
}

export class EffectVoid extends EffectScalar {
  type = 'void' as const

  protected override toExpression(): string {
    return `${SCHEMA}.Void`
  }
}
